package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {









    @Test
    public void testCreateNumber_IntegerTypes() {
        // Integer
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Integer.valueOf(-123), NumberUtils.createNumber("-123"));

        // Long
        assertEquals(Long.valueOf(123456789L), NumberUtils.createNumber("123456789"));

        // BigInteger (Exceeding Long)
        String bigIntStr = "123456789012345678901234567890";
        Number bigIntResult = NumberUtils.createNumber(bigIntStr);
        assertTrue(bigIntResult instanceof BigInteger);
        assertEquals(new BigInteger(bigIntStr), bigIntResult);

        // Long suffix 'L'
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123l"));

        // BigInteger suffix 'L'
        String bigLStr = "123456789012345678901234567890L";
        Number bigLResult = NumberUtils.createNumber(bigLStr);
        assertTrue(bigLResult instanceof BigInteger);
    }












}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {











    @Test
    public void testCreateNumber_FloatingPointTypes() {
        // Float suffix 'F'
        assertEquals(Float.valueOf(123.45f), NumberUtils.createNumber("123.45F"));

        // Double suffix 'D'
        assertEquals(Double.valueOf(123.45), NumberUtils.createNumber("123.45D"));

        // Double suffix 'd'
        assertEquals(Double.valueOf(123.45), NumberUtils.createNumber("123.45d"));

        // Scientific notation (No suffix) -> Double/BigDecimal
        assertEquals(Double.valueOf(1.23e2), NumberUtils.createNumber("1.23e2"));

        // Decimal point (No suffix) -> Double/BigDecimal
        assertEquals(Double.valueOf(123.45), NumberUtils.createNumber("123.45"));

        // BigDecimal fallback
        // If it's too big for Float/Double, it hits BigDecimal
        String hugeDecimal = "12345678901234567890.1234567890";
        Number hugeResult = NumberUtils.createNumber(hugeDecimal);
        assertTrue(hugeResult instanceof BigDecimal);
    }










}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {













    @Test
    public void testCreateNumber_ScientificNotationEdgeCases() {
        // Exp before Dec (Invalid)
        try {
            NumberUtils.createNumber("1e2.3");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            assertTrue(e.getMessage().contains("is not a valid number"));
        }

        // Exp with suffix
        // e.g., 1.23e2f -> numeric is 1.23e2, lastChar is f, exp is 2
        assertEquals(Float.valueOf(123.0f), NumberUtils.createNumber("1.23e2f"));
    }








}

