package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {

















    @Test
    public void testCreateNumber_PrecisionAndZeroChecks() {
        // Test the logic: if (f.floatValue() == 0.0F && !allZeros) -> return Double/BigDecimal
        // String "0.0000000000000000000000000000000000000000001f"
        // This is so small that Float becomes 0.0, but it's not all zeros.
        String tiny = "0.0000000000000000000000000000000000000000001f";
        Number res = NumberUtils.createNumber(tiny);
        // Should fall through from Float to Double or BigDecimal
        assertFalse(res instanceof Float);

        // Test allZeros = true case
        assertEquals(Float.valueOf(0.0f), NumberUtils.createNumber("0.0e0f"));

        // Test allZeros = false case (mantissa 0, exp 0 but string had non-zeros)
        // "0.000e0" -> mant=0, exp=0. isAllZeros(0) is true.
        // The code uses isAllZeros(mant) && isAllZeros(exp).
        // If input is "0.0e0", mant is "0", exp is "0".
        Number zeroRes = NumberUtils.createNumber("0.0e0");
        assertNotNull(zeroRes);
    }




}

