package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {





















    @Test
    public void testCreateNumber_LargeLongSuffix() {
        // Test the try-catch block for Long vs BigInteger
        String tooBigForLong = "9223372036854775808L"; // Long.MAX_VALUE + 1
        Number res = NumberUtils.createNumber(tooBigForLong);
        assertTrue(res instanceof BigInteger);
        assertEquals(new BigInteger(tooBigForLong.substring(0, tooBigForLong.length()-1)), res);
    }
